<?php $id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM borrowers WHERE id=?');$s->execute([$id]);$b=$s->fetch();if(!$b)redirect('?page=borrowers');$s=$pdo->prepare('SELECT l.*,i.asset_code,e.name equipment FROM loans l JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE l.borrower_id=? ORDER BY l.issued_at DESC');$s->execute([$id]);$loans=$s->fetchAll();layout_start('Borrower details','borrowers'); ?><div class="page-heading"><div><a class="back-link" href="?page=borrowers">← Borrowers</a><h1><?=h($b['full_name'])?></h1><p class="muted">Borrower since <?=date('j M Y',strtotime($b['registered_at']))?></p></div><div class="button-row"><a class="button secondary" href="?page=borrower-form&id=<?=$id?>">Edit details</a><a class="button primary" href="?page=request-form&borrower=<?=$id?>">＋ New request</a></div></div><div class="detail-grid"><section class="panel"><h2>Contact details</h2><dl class="detail-list"><dt>Phone</dt><dd><?=h($b['phone'])?></dd><dt>Email</dt><dd><?=h($b['email']?:'Not provided')?></dd><dt>Address</dt><dd><?=nl2br(h($b['address']?:'Not provided'))?></dd><dt>Status</dt><dd><span class="badge <?=strtolower($b['status'])?>"><?=h($b['status'])?></span></dd><dt>Online account</dt><dd><?=$b['password_hash']?'Yes · last sign-in '.($b['last_login_at']?date('j M Y, g:i a',strtotime($b['last_login_at'])):'never'):'No (staff-created record)'?></dd><dt>Notes</dt><dd><?=nl2br(h($b['notes']?:'None'))?></dd></dl></section><section class="panel"><h2>Borrowing history</h2><?php if(!$loans): ?><p class="muted">No loans recorded.</p><?php else: ?><div class="table-scroll"><table><thead><tr><th>Equipment</th><th>Issued</th><th>Due</th><th>Returned</th></tr></thead><tbody><?php foreach($loans as $l): ?><tr><td><?=h($l['equipment'])?> <small class="cell-sub"><?=h($l['asset_code'])?></small></td><td><?=date('j M Y',strtotime($l['issued_at']))?></td><td><?=date('j M Y',strtotime($l['due_date']))?></td><td><?=$l['returned_at']?date('j M Y',strtotime($l['returned_at'])):'Active'?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div><?php layout_end();
